from __future__ import absolute_import
import time
from functools import partial
from selenium.webdriver.common.by import By
from selenium.common.exceptions import NoSuchElementException, ElementClickInterceptedException
from .panels.navigation import NavigationPanel
from .panels.view import ViewPanel
from .panels.details import DetailPanel
from .common_page import CommonPage


def wait_for_filter_counter_success(count):
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            retry_times = count
            while retry_times:
                retry_times -= 1
                try:
                    func(self, *args, **kwargs)
                    break
                except ElementClickInterceptedException:
                    raise ElementClickInterceptedException if not retry_times else self.clear_all_selections()
        return wrapper
    return decorator


class Performance(CommonPage):
    """
    The class corresponding to Performance page on selenium_coam web, all operations under Performance
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self):
        if not self._instance_dict:
            self._instance_dict = {"BTS Counters": BTSCountersPage(),
                                   "Transport Counters": TransportCountersPage(),
                                   "Real-time Measurements": RealTimeMeasurementsPage()}
        super(Performance, self).__init__(self._instance_dict)


class PerformanceCommonAction(NavigationPanel, ViewPanel, DetailPanel):
    _CLEAR_SELECTION_BUTTON_XPATH = '//ui-button[@a-title="Clear all selections"]//button'
    _SELECT_COUNTER_FILTER_XPATH = "//ui-text-input[@a-placeholder='Selected counter']//input"
    _SELECT_COUNTER_XPATH = "//div[@class='pm-counters-table-container']//tr/th[contains(text(), '{}')]"
    _DISPLAY_DATA_DROPDOWN_BUTTON = "//span[text()='Display data for:']/following-sibling::ui-select//button"
    _EXPORT_TO_CSV_BUTTON_XPAHT = '//div[contains(@class, "performance-management")]//button[contains(text(), ' \
                                  '"Export to CSV")]'
    _AVAILABLE_TIMESTAMPS_DROPDOWN_XPATH = "//ul[@class='dropdown-menu scroll-dropdown-native']//li"
    _AVAILABLE_OBJECT_FILTER_XPATH = "//ui-text-input[contains(@a-placeholder, 'Available Object') or " \
                                     "contains(@a-placeholder, 'Object name')]//input"
    _VISIBLE_OBJECT_XPATH = '//div[@class="tab-pane ng-scope active"]//i[contains(@class, "expand-icon")]'
    _AVAILABLE_OBJECT_XPATH = "//div[@class='pm-tree-elements']//span[contains(@title, '{}')]"
    _COUNTERS_TIMESTAMPS_XPATH = "//div[@class='pm-counters-table-container']//tbody/tr/td[1]"
    _COUNTERS_NUMBERS_XPATH = "//div[@class='pm-counters-table-container']//tbody/tr/td[2]"
    _FULL_PATH_TH_XPATH = '//tr//th[text()="Full path"]/..//th'
    _TARGET_COUNTER_TR_XPATH = '//div[@class="pm-counters-table-container"]//tbody/tr/td[{}]'
    _EXPAND_ICON_XPATH = '//*[contains(@class, "expand-icon pm-tree-node-arrow")]'
    _instance = None

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(PerformanceCommonAction, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def _select_counter_on_first_page(self, counter_span_xpath):
        for index, _ in enumerate(self.driver.find_elements_by_xpath(counter_span_xpath)):
            elem = self.driver.find_elements_by_xpath(counter_span_xpath)[index]
            if index < 4 and not elem.is_selected():
                elem.click()
            time.sleep(1)

    def _select_counter_over_fist_page(self, counter_span_xpath, counter_checkbox_xpath):
        for index, _ in enumerate(self.driver.find_elements_by_xpath(counter_span_xpath)):
            elems = self.driver.find_elements_by_xpath(counter_span_xpath)
            if not self.driver.find_elements_by_xpath(counter_checkbox_xpath)[index].is_selected():
                elems[index].click()
            time.sleep(1)

    def _select_counters(self, counter_id, counter_checkbox_xpath):
        """
        Used to select several counters with same name. Due to page refresh after every checkbox clicking, so re-finding
        checkbox elements is needed.
        """
        counter_span_xpath = counter_checkbox_xpath.format(counter_id)
        counter_checkbox_xpath = (counter_checkbox_xpath.strip('span') + 'input').format(counter_id)

        for i in range(5):
            self.wait_for_visibility((By.XPATH, counter_span_xpath))
            if i == 0:
                self._select_counter_on_first_page(counter_span_xpath)
                counter_xpath = counter_span_xpath
            else:
                self._select_counter_over_fist_page(counter_span_xpath, counter_checkbox_xpath)
                counter_xpath = counter_checkbox_xpath
            elems = self.driver.find_elements_by_xpath(counter_xpath)
            self.driver.execute_script("arguments[0].scrollIntoView();", elems[-1])

    def clear_all_selections(self):
        """
        Method for clicking erase button to clear all counter selections
        :return:
        """
        self.click_enabled_element((By.XPATH, self._CLEAR_SELECTION_BUTTON_XPATH))
        self.clear_text_of_enable_element((By.XPATH, self._AVAILABLE_OBJECT_FILTER_XPATH))
        self.wait_for_text_present_in_attribute(self._AVAILABLE_OBJECT_FILTER_XPATH, "class", "ng-empty")

    @wait_for_filter_counter_success(count=2)
    def filter_counter(self, counter_id, counter_checkbox_xpath):
        """
        Method for filtering corresponding object name under navigation panel and wait for object display
        :param counter_id: str, counter id, e.g. "M55113C00001"
        :param counter_checkbox_xpath: str, checkbox xpath
        """
        self.wait_for_visibility_by_xpath(self._EXPAND_ICON_XPATH)
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._AVAILABLE_OBJECT_FILTER_XPATH), counter_id)
        self.wait_for_text_present_in_attribute(self._AVAILABLE_OBJECT_FILTER_XPATH, "class", "ng-not-empty")
        self._select_counters(counter_id, counter_checkbox_xpath)

    def input_counter_id(self, counter_id, timeout):
        """
        Keyword for inputting counter id under view panel and wait counter info for display.
        :param counter_id: str, input counter id and filter corresponding counters
        :param timeout: int, wait for timeout seconds until element will become enable
        TODO: this method will be reserved here for a period of time
        """
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._SELECT_COUNTER_FILTER_XPATH),
                                                     counter_id, timeout)
        self.wait_for_visibility((By.XPATH, self._SELECT_COUNTER_XPATH.format(counter_id)))

    def get_all_available_timestamps_counter_info(self, timeout_for_loading_available_counters):
        """
        Keyword for select it if all available timestamps exist and get counter info under view panel
        :param timeout_for_loading_available_counters: int, wait time for all available timestamps info display
        :return: dictionary for counter info contained timestamps and corresponding packets
        TODO: this method will be reserved here for a period of time
        """
        self.click_and_wait_for_corresponding_element_visible(self._DISPLAY_DATA_DROPDOWN_BUTTON,
                                                              self._AVAILABLE_TIMESTAMPS_DROPDOWN_XPATH)
        try:
            self.driver.find_elements_by_xpath(self._AVAILABLE_TIMESTAMPS_DROPDOWN_XPATH)[-1].click()
            time.sleep(timeout_for_loading_available_counters)
        except NoSuchElementException:
            raise
        return self.get_dict_from_elements_by_xpath(self._COUNTERS_TIMESTAMPS_XPATH,
                                                    self._COUNTERS_NUMBERS_XPATH, " ")

    def get_counter_info(self, full_path, timeout_for_loading_available_counters):
        """
        Method for getting counter info
        :param full_path: str, full path of one counter, can be used to locate counter
                          when different counters have same id
        :param timeout_for_loading_available_counters: int, wait time for all available timestamps info display
        :return: dict
        """
        self.driver.execute_script("arguments[0].scrollIntoView();",
                                   self.driver.find_element_by_xpath(self._DISPLAY_DATA_DROPDOWN_BUTTON))
        self.click_and_wait_for_corresponding_element_visible(self._DISPLAY_DATA_DROPDOWN_BUTTON,
                                                              self._AVAILABLE_TIMESTAMPS_DROPDOWN_XPATH)
        try:
            self.driver.find_elements_by_xpath(self._AVAILABLE_TIMESTAMPS_DROPDOWN_XPATH)[-1].click()
            self.wait_for_visibility_by_xpath(self._COUNTERS_TIMESTAMPS_XPATH, timeout_for_loading_available_counters)
        except NoSuchElementException:
            raise

        if full_path:
            for index, elem in enumerate(self.driver.find_elements_by_xpath(self._FULL_PATH_TH_XPATH)[1:]):
                if full_path == elem.text.strip():
                    target_th = index + 2
                    break
            else:
                raise NoSuchElementException("can not find target elem by given full_path, "
                                             "please check if it is completed.")
            return self.get_dict_from_elements_by_xpath(
                self._COUNTERS_TIMESTAMPS_XPATH,
                self._TARGET_COUNTER_TR_XPATH.format(target_th),
                " "
            )
        return self.get_dict_from_elements_by_xpath(self._COUNTERS_TIMESTAMPS_XPATH,
                                                    self._COUNTERS_NUMBERS_XPATH, " ")

    def export_counters_info_to_csv(self, download_timeout):
        """
        Downloading csv file by clicking "Export to CSV" button
        :param download_timeout: int, time for downloading
        :return: str, file path
        """
        start_time = time.time()
        self.click_enabled_element_after_visible((By.XPATH, self._EXPORT_TO_CSV_BUTTON_XPAHT))
        return self.download_files(start_time, download_timeout)


class BTSCountersPage(object):
    """
    As a class will be called by Performance,
    all operations on BTS Counters will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['Performance', 'Performance Management', 'BTS Counters']

    def __init__(self):
        self._navigation_panel = BTSCountersPageNavigationPanel()
        self._view_panel = BTSCountersPageViewPanel()

    def get_bts_counters_info(self, counter_id, full_path=None, timeout_for_loading_available_counters=5):
        """
        Keyword for getting bts counters through selecting from navigation panel and view panel. You can input
        object name containing serial number(such as: "NRBTS-1")
        corresponding object name under navigation panel
        :param counter_id: str, input counter id and filter corresponding counters
        :param full_path: full path of one counter, e.g. "BTS/NRBTS-1/NE1CB/E1_SETUP_REQUEST_SENT_BTS"
        :param timeout_for_loading_available_counters: int, wait time for all available timestamps display
        :return: dictionary for counter info contained timestamps and corresponding packets
        """
        self._navigation_panel.filter_counter(counter_id)
        counter_info = self._view_panel.get_counter_info(full_path, timeout_for_loading_available_counters)
        self._navigation_panel.clear_all_selections()
        return counter_info


class BTSCountersPageNavigationPanel(NavigationPanel):
    _AVAILABLE_COUNTER_CHECKBOX_XPATH = '//span[contains(text(), "{}")]/../../preceding-sibling::label//span'

    def __init__(self):
        super(BTSCountersPageNavigationPanel, self).__init__()
        self.common_actions = {
            'filter_counter': partial(PerformanceCommonAction().filter_counter,
                                      counter_checkbox_xpath=self._AVAILABLE_COUNTER_CHECKBOX_XPATH),
            'clear_all_selections': PerformanceCommonAction().clear_all_selections
        }
        self.__dict__.update(self.common_actions)


class BTSCountersPageViewPanel(ViewPanel):
    def __init__(self):
        super(BTSCountersPageViewPanel, self).__init__()
        self.common_actions = {
            'get_counter_info': PerformanceCommonAction().get_counter_info,
        }
        self.__dict__.update(self.common_actions)


